    rightMin[n - 1] = A[n - 1];
    for (int i = n - 2; i >= 0; i--)
        rightMin[i] = A[i] < rightMin[i + 1] ? A[i] : rightMin[i + 1];
    int leftMax = A[0], count = 0;
