bool MaximumDrop(const int A[], int n, long long &answer) {
    if (n < 2) return false;
    int previousMax = A[0];
    answer = (long long)A[0] - A[1];
    for (int j = 1; j < n; j++) {
        long long candidate = (long long)previousMax - A[j];
        if (candidate > answer) answer = candidate;
        if (A[j] > previousMax) previousMax = A[j];
