int MinimumTerms(const ALGraph &G) {
    int n = G.vexnum;
    int *indegree = new int[n]();
    int *q = new int[n]();
    for (int v = 0; v < n; v++) {
        for (ArcNode *p = G.vertices[v].firstarc; p != NULL; p = p->nextarc)
            indegree[p->adjvex]++;
    }
    int front = 0, rear = 0;
    for (int v = 0; v < n; v++)
        if (indegree[v] == 0) q[rear++] = v;
    int terms = 0, processed = 0;
    while (front < rear) {
        int end = rear;
        terms++;
        while (front < end) {
            int v = q[front++];
            processed++;
            for (ArcNode *p = G.vertices[v].firstarc; p != NULL; p = p->nextarc) {
                int w = p->adjvex;
                indegree[w]--;
                if (indegree[w] == 0) q[rear++] = w;
            }
        }
    }
    delete[] indegree;
    delete[] q;
    if (processed < n) return -1;
    return terms;
}

